import { useState } from 'react';
import { Icon } from '@iconify/react';

export default function Admin() {
  const [books, setBooks] = useState([]);

  return (
    <div className="max-w-7xl mx-auto px-4 py-12">
      <div className="mb-8 flex justify-between items-center">
        <h1 className="text-3xl font-bold text-green-700 dark:text-green-400">Admin Dashboard</h1>
        <button className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg inline-flex items-center gap-2">
          <Icon icon="ph:plus-duotone" className="w-5 h-5" />
          Add Book
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
        {[
          { label: 'Total Books', value: books.length },
          { label: 'Hadith Collections', value: '0' },
          { label: 'Users', value: '1' },
          { label: 'Downloads', value: '0' },
        ].map(stat => (
          <div key={stat.label} className="bg-white dark:bg-gray-800 p-4 rounded-xl shadow text-center">
            <div className="text-2xl font-bold text-green-600">{stat.value}</div>
            <div className="text-sm text-gray-500">{stat.label}</div>
          </div>
        ))}
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-2xl shadow p-6">
        <h2 className="text-xl font-bold mb-4">Manage Books</h2>
        <p className="text-gray-500">Book management interface coming soon with full CRUD operations.</p>
      </div>
    </div>
  );
}
